25	MG_AR_004	應收帳款統計表(已)	\N	SELECT S.SPR_COR_NAME,SPR_TEL,SPR_FAX,SPR_ADDR\r\n,M.CUM_NO,C.CUM_NAME,C.CUM_ADVANCE_AMOUNT\r\n,SUM(M.SMT_TOTAL+M.SMT_TAX) C_AMOUNT\r\n,SUM(M.SMT_NOT_CLEAN) C_NOT_CLEAN\r\nFROM TBL_SHIP M INNER JOIN TBL_CUSTOMER C ON M.CUM_NO=C.CUM_NO\r\n,TBL_SYS_PARAM S	WHERE M.SMT_STATUS>0	GROUP BY S.SPR_COR_NAME,SPR_TEL,SPR_FAX,SPR_ADDR\r\n,M.CUM_NO,C.CUM_NAME,C.CUM_ADVANCE_AMOUNT	\N	{"ReportVersion": "2026.3.3", "ReportGuid": "871e3ce6d4bd41728173ae36811cc5e5", "ReportName": "Report", "ReportAlias": "Report", "ReportCreated": "/Date(1789005813161+0800)/", "ReportChanged": "/Date(1789005813161+0800)/", "EngineVersion": "EngineV2", "ReportUnit": "Centimeters", "ScriptLanguage": "CSharp", "UsePlatformDependentScript": false, "CalculationMode": "Interpretation", "Dictionary": {"DataSources": {"0": {"Ident": "StiDataTableSource", "Name": "srpmeta", "NameInSource": "srpmeta", "Alias": "srpmeta", "Columns": {"0": {"Name": "srp_id", "NameInSource": "srp_id", "Alias": "srp_id", "Type": "System.String"}, "1": {"Name": "srp_code", "NameInSource": "srp_code", "Alias": "srp_code", "Type": "System.String"}, "2": {"Name": "srp_name", "NameInSource": "srp_name", "Alias": "srp_name", "Type": "System.String"}, "3": {"Name": "srp_description", "NameInSource": "srp_description", "Alias": "srp_description", "Type": "System.String"}}}, "1": {"Ident": "StiDataTableSource", "Name": "root", "NameInSource": "root", "Alias": "root", "Columns": {"0": {"Name": "spr_cor_name", "NameInSource": "spr_cor_name", "Alias": "spr_cor_name", "Type": "System.String"}, "1": {"Name": "spr_tel", "NameInSource": "spr_tel", "Alias": "spr_tel", "Type": "System.String"}, "2": {"Name": "spr_fax", "NameInSource": "spr_fax", "Alias": "spr_fax", "Type": "System.String"}, "3": {"Name": "spr_addr", "NameInSource": "spr_addr", "Alias": "spr_addr", "Type": "System.String"}, "4": {"Name": "cum_no", "NameInSource": "cum_no", "Alias": "cum_no", "Type": "System.String"}, "5": {"Name": "cum_name", "NameInSource