47	ST_RPT_11	客戶發票統計表	\N	SELECT\r\nM.CUM_NO\r\n,C.CUM_NAME\r\n,C.CUM_UNIFORM_NO\r\n,C.CUM_INV_ADDR\r\n,SUM(D.SMD_QTY*D.SMD_UNIT_PRICE*10) C_TOTAL\r\n,C.CUM_INV_RATE\r\n,ROUND(SUM(D.SMD_QTY*D.SMD_UNIT_PRICE*10)*C.CUM_INV_RATE/1.05,0) C_INV_NET_AMOUNT\r\n,ROUND(ROUND(SUM(D.SMD_QTY*D.SMD_UNIT_PRICE*10)*C.CUM_INV_RATE/1.05,0)*.05,0)  C_TAX\r\n,ROUND(SUM(D.SMD_QTY*D.SMD_UNIT_PRICE*10)*C.CUM_INV_RATE/1.05,0)\r\n  +ROUND(ROUND(SUM(D.SMD_QTY*D.SMD_UNIT_PRICE*10)*C.CUM_INV_RATE/1.05,0)*.05,0)  C_AMOUNT\r\n,S.SPR_COR_NAME,S.SPR_TEL,S.SPR_FAX\r\nFROM TBL_SHIP M INNER JOIN TBL_SHIP_DT D ON M.SMT_NO=D.SMT_NO\r\nINNER JOIN TBL_CUSTOMER C ON M.CUM_NO=C.CUM_NO\r\nINNER JOIN TBL_PRODUCT P ON D.PRD_NO=P.PRD_NO\r\nINNER JOIN TBL_EMPLOYE E ON M.EPY_NO=E.EPY_NO\r\n,TBL_SYS_PARAM S	WHERE M.SMT_STATUS>0\r\nAND C.CUM_INV_RATE > 0	GROUP BY M.CUM_NO,C.CUM_NAME,C.CUM_INV_RATE\r\n,C.CUM_UNIFORM_NO\r\n,C.CUM_INV_ADDR\r\n,S.SPR_COR_NAME,S.SPR_TEL,S.SPR_FAX	\N	{"ReportVersion": "2026.3.3", "ReportGuid": "9c82f954bf5a4287ab5000a6a7a33b25", "ReportName": "Report", "ReportAlias": "Report", "ReportCreated": "/Date(1789005813308+0800)/", "ReportChanged": "/Date(1789005813308+0800)/", "EngineVersion": "EngineV2", "ReportUnit": "Centimeters", "ScriptLanguage": "CSharp", "UsePlatformDependentScript": false, "CalculationMode": "Interpretation", "Dictionary": {"DataSources": {"0": {"Ident": "StiDataTableSource", "Name": "srpmeta", "NameInSource": "srpmeta", "Alias": "srpmeta", "Columns": {"0": {"Name": "srp_id", "NameInSource": "srp_id", "Alias": "srp_id", "Type": "System.String"}, "1": {"Name": "srp_code", "NameInSource": "srp_code", "Alias": "srp_code", "Type": "System.String"}, "2": {"Name": "srp_name", "NameInSource": "srp_name", "Alias": "srp_name", "Type": "System.String"}, "3": {"Name": "srp_description", "NameInSource": "srp_description", "Alias": "srp_description", "Type": "System.String"}}}, "1": {"Ident": "StiDataTableSource", "Name": "root", "NameInSource": "root", "Alias": "root", "Columns": {"