37	ST_RPT_03	客戶績效分析表	\N	SELECT\r\nM.CUM_NO\r\n,C.CUM_NAME\r\n, CASE SUM(D.SMD_QTY*D.SMD_UNIT_PRICE)\r\n  WHEN 0 THEN 0\r\n  ELSE (SUM(D.SMD_QTY*D.SMD_UNIT_PRICE)-SUM(D.SMD_QTY*D.SMD_COST))/SUM(D.SMD_QTY*D.SMD_UNIT_PRICE)*100\r\n  END C_RATE\r\n,SUM(D.SMD_QTY) C_QTY\r\n,SUM(D.SMD_QTY*D.SMD_UNIT_PRICE) C_TOTAL\r\n,SUM(D.SMD_QTY*D.SMD_COST) C_COST\r\n,SUM(D.SMD_QTY*D.SMD_UNIT_PRICE)-SUM(D.SMD_QTY*D.SMD_COST) C_PROFIT\r\n,S.SPR_COR_NAME,S.SPR_TEL,S.SPR_FAX\r\nFROM TBL_SHIP M INNER JOIN TBL_SHIP_DT D ON M.SMT_NO=D.SMT_NO\r\nINNER JOIN TBL_CUSTOMER C ON M.CUM_NO=C.CUM_NO\r\nINNER JOIN TBL_PRODUCT P ON D.PRD_NO=P.PRD_NO\r\nINNER JOIN TBL_EMPLOYE E ON M.EPY_NO=E.EPY_NO\r\n,TBL_SYS_PARAM S	WHERE M.SMT_STATUS>0	GROUP BY M.CUM_NO,C.CUM_NAME\r\n,S.SPR_COR_NAME,S.SPR_TEL,S.SPR_FAX\r\n	\N	{"ReportVersion": "2026.3.3", "ReportGuid": "38cf3bf202c24800bbf72fa77e02aae9", "ReportName": "Report", "ReportAlias": "Report", "ReportCreated": "/Date(1789005813269+0800)/", "ReportChanged": "/Date(1789005813269+0800)/", "EngineVersion": "EngineV2", "ReportUnit": "Centimeters", "ScriptLanguage": "CSharp", "UsePlatformDependentScript": false, "CalculationMode": "Interpretation", "Dictionary": {"DataSources": {"0": {"Ident": "StiDataTableSource", "Name": "srpmeta", "NameInSource": "srpmeta", "Alias": "srpmeta", "Columns": {"0": {"Name": "srp_id", "NameInSource": "srp_id", "Alias": "srp_id", "Type": "System.String"}, "1": {"Name": "srp_code", "NameInSource": "srp_code", "Alias": "srp_code", "Type": "System.String"}, "2": {"Name": "srp_name", "NameInSource": "srp_name", "Alias": "srp_name", "Type": "System.String"}, "3": {"Name": "srp_description", "NameInSource": "srp_description", "Alias": "srp_description", "Type": "System.String"}}}, "1": {"Ident": "StiDataTableSource", "Name": "root", "NameInSource": "root", "Alias": "root", "Columns": {"0": {"Name": "cum_no", "NameInSource": "cum_no", "Alias": "cum_no", "Type": "System.String"}, "1": {"Name": "cum_name", "NameInSource": "cum_name", "Alias": 