46	ST_RPT_10	運輸人員業績分析表	\N	SELECT A.DELIVER_NO,A.EPY_NAME,A.SMT_DATE,A.TOTAL,B.RETURN_TOTAL\r\nFROM\r\n(  SELECT DELIVER_NO,EPY_NAME,SMT_DATE\r\n  ,SUM(TOTAL) TOTAL\r\n  FROM\r\n  (  SELECT 1 DELIVER ,B.SMD_SEQNO,A.SMT_DELIVER1 DELIVER_NO,C.EPY_NAME,A.SMT_DATE,A.SMT_NO\r\n    ,B.SMD_QTY*B.SMD_UNIT_PRICE*0.5 TOTAL\r\n    FROM TBL_SHIP a\r\n    INNER JOIN TBL_SHIP_DT B ON A.SMT_NO=B.SMT_NO\r\n    INNER JOIN TBL_EMPLOYE C ON A.SMT_DELIVER1=C.EPY_NO\r\n    WHERE B.SMD_QTY >0\r\n\r\n    UNION\r\n\r\n    SELECT 2 DELIVER ,B.SMD_SEQNO,A.SMT_DELIVER2 DELIVER_NO,C.EPY_NAME,A.SMT_DATE,A.SMT_NO\r\n    ,B.SMD_QTY*B.SMD_UNIT_PRICE*0.5 TOTAL\r\n    FROM TBL_SHIP a\r\n    INNER JOIN TBL_SHIP_DT B ON A.SMT_NO=B.SMT_NO\r\n    INNER JOIN TBL_EMPLOYE C ON A.SMT_DELIVER2=C.EPY_NO\r\n    WHERE B.SMD_QTY >0\r\n  ) A\r\n  GROUP BY DELIVER_NO,EPY_NAME,SMT_DATE\r\n) A\r\nLEFT JOIN\r\n(  SELECT DELIVER_NO,EPY_NAME,SMT_DATE\r\n  ,SUM(TOTAL) RETURN_TOTAL\r\n  FROM\r\n  (\r\n    SELECT 1 DELIVER ,B.SMD_SEQNO,A.SMT_DELIVER1 DELIVER_NO,C.EPY_NAME,A.SMT_DATE,A.SMT_NO\r\n    ,B.SMD_QTY*B.SMD_UNIT_PRICE*0.5 TOTAL\r\n    FROM TBL_SHIP a\r\n    INNER JOIN TBL_SHIP_DT B ON A.SMT_NO=B.SMT_NO\r\n    INNER JOIN TBL_EMPLOYE C ON A.SMT_DELIVER1=C.EPY_NO\r\n    WHERE B.SMD_QTY <0\r\n\r\n  UNION\r\n\r\n    SELECT 2 DELIVER ,B.SMD_SEQNO,A.SMT_DELIVER2 DELIVER_NO,C.EPY_NAME,A.SMT_DATE,A.SMT_NO\r\n    ,B.SMD_QTY*B.SMD_UNIT_PRICE*0.5 TOTAL\r\n    FROM TBL_SHIP a\r\n    INNER JOIN TBL_SHIP_DT B ON A.SMT_NO=B.SMT_NO\r\n    INNER JOIN TBL_EMPLOYE C ON A.SMT_DELIVER2=C.EPY_NO\r\n    WHERE B.SMD_QTY <0\r\n  ) A\r\n  GROUP BY DELIVER_NO,EPY_NAME,SMT_DATE\r\n) B\r\nON A.DELIVER_NO=B.DELIVER_NO\r\nAND A.SMT_DATE=B.SMT_DATE	\N	\N	ORDER BY A.DELIVER_NO,A.SMT_DATE 	{"ReportVersion": "2026.3.3", "ReportGuid": "f7134f1c070e40afad9a1e4c5ff8c686", "ReportName": "Report", "ReportAlias": "Report", "ReportCreated": "/Date(1789005813300+0800)/", "ReportChanged": "/Date(1789005813300+0800)/", "EngineVersion": "EngineV2", "ReportUnit": "Centimeters", "ScriptLanguage": "CSharp", "UsePlatformDependentScript": false, "CalculationMode": "Interpretation", "Dictionary": {"DataSources": {"0": {"Ident": "StiDataTableSource", "Name": "srpmeta", "NameInSource": "srpmeta", "Alias": "srpmeta", "Columns": {"0": {"Name": "srp_id", "NameInSource": "srp_id", "Alias": "srp_id", "Type": "System.String"}, "1": {"Name": "srp_code", "NameInSource": "srp_code", "Alias": "srp_code", "Type": "System.String"}, "2": {"Name": "srp_name", "NameInSource": "srp_name", "Alias": "srp_name", "Type": "System.String"}, "3": {"Name": "srp_description", "NameInSource": "srp_description", "Alias": "srp_description", "Type": "System.String"}}}, "1": {"Ident": "StiDataTableSource", "Name": "root", "NameInSource": "root", "Alias": "root", "Columns": {"0": {"Name": "deliver_no", "NameInSource": "deliver_no", "Alias": "deliver_no", "Type": "System.String"}, "1": {"Name": "epy_name", "NameInSource": "epy_name", "Alias": "epy_name", "Type": "System.String"}, "2": {"Name": "smt_date", "NameInSource": "smt_date", "Alias": "smt_date", "Type": "System.DateTime"}, "3": {"Name": "total", "NameInSource": "total", "Alias": "total", "Type": "System.Decimal"}, "4": {"Name": "return_total", "NameInSource": "return_total", "Alias": "return_total", "Type": "System.Decimal"}}}}}, "Pages": {"0": {"Ident": "StiPage", "Name": "Page1", "Guid": "b1b64c7991cc426eae73e2d88e016f0b", "Interaction": {"Ident": "StiInteraction"}, "Border": ";;;;;;;solid:Black", "Brush": "solid:", "Components": {"0": {"Ident": "StiPageHeaderBand", "Name": "ppHeaderBand1", "Guid": "bb20f7f410d24daab9a693c78f72795b", "CanGrow": true, "ClientRectangle": "0,0.0,19.7379,2.3813", "Interaction": {"Ident": "StiInteraction"}, "Border": ";;;;;;;solid:Black", "Brush": "solid:", "Components": {"0": {"Ident": "StiText", "Name": "ppLabel2", "Guid": "c6da02048d8146c0a7767b654a06baca", "ClientRectangle": "0.635,0.4498,1.7727,0.4233", "Interaction": {"Ident": "StiInteraction"}, "Text": {"Value": "製表