39	ST_RPT_05	每日銷售業績統計圖	\N	SELECT (DATE '1900-01-01' + (FLOOR((m.smt_date::date - DATE '1900-01-01') / 1)::int * 1)) smt_date\n,sum(m.smt_total) amount\n,S.SPR_COR_NAME\nFROM TBL_SHIP M,TBL_SYS_PARAM S	WHERE M.SMT_STATUS>0	group by (DATE '1900-01-01' + (FLOOR((m.smt_date::date - DATE '1900-01-01') / 1)::int * 1))\n,S.SPR_COR_NAME	order by smt_date	{"ReportVersion": "2026.3.3", "ReportGuid": "04073910a0534220826fe94a95331eca", "ReportName": "Report", "ReportAlias": "Report", "ReportCreated": "/Date(1789006650804+0800)/", "ReportChanged": "/Date(1789006650804+0800)/", "EngineVersion": "EngineV2", "ReportUnit": "Centimeters", "ScriptLanguage": "CSharp", "UsePlatformDependentScript": false, "CalculationMode": "Interpretation", "Dictionary": {"DataSources": {"0": {"Ident": "StiDataTableSource", "Name": "srpmeta", "NameInSource": "srpmeta", "Alias": "srpmeta", "Columns": {"0": {"Name": "srp_id", "NameInSource": "srp_id", "Alias": "srp_id", "Type": "System.String"}, "1": {"Name": "srp_code", "NameInSource": "srp_code", "Alias": "srp_code", "Type": "System.String"}, "2": {"Name": "srp_name", "NameInSource": "srp_name", "Alias": "srp_name", "Type": "System.String"}, "3": {"Name": "srp_description", "NameInSource": "srp_description", "Alias": "srp_description", "Type": "System.String"}}}, "1": {"Ident": "StiDataTableSource", "Name": "root", "NameInSource": "root", "Alias": "root", "Columns": {"0": {"Name": "smt_date", "NameInSource": "smt_date", "Alias": "smt_date", "Type": "System.DateTime"}, "1": {"Name": "amount", "NameInSource": "amount", "Alias": "amount", "Type": "System.Decimal"}, "2": {"Name": "spr_cor_name", "NameInSource": "spr_cor_name", "Alias": "spr_cor_name", "Type": "System.String"}}}}}, "Pages": {"0": {"Ident": "StiPage", "Name": "Page1", "Guid": "0656d7b752a34b0a8da4a7a8624f8471", "Interaction": {"Ident": "StiInteraction"}, "Border": ";;;;;;;solid:Black", "Brush": "solid:", "Components": {"0": {"Ident": "StiReportTitleBand", "Name": "ppTitleBand1", "Guid": "37