42	ST_RPT_06-2	銷售業績統計圖(3日週期)	\N	SELECT (DATE '1900-01-01' + (FLOOR((m.smt_date::date - DATE '1900-01-01') / 3)::int * 3)) smt_date\n,sum(m.smt_total) amount\n,S.SPR_COR_NAME\nFROM TBL_SHIP M,TBL_SYS_PARAM S	WHERE M.SMT_STATUS>0	group by (DATE '1900-01-01' + (FLOOR((m.smt_date::date - DATE '1900-01-01') / 3)::int * 3))\n,S.SPR_COR_NAME	order by smt_date	{"ReportVersion": "2026.3.3", "ReportGuid": "961d9265f2c84ab5a570fd7f6f1b79d5", "ReportName": "Report", "ReportAlias": "Report", "ReportCreated": "/Date(1789006650814+0800)/", "ReportChanged": "/Date(1789006650814+0800)/", "EngineVersion": "EngineV2", "ReportUnit": "Centimeters", "ScriptLanguage": "CSharp", "UsePlatformDependentScript": false, "CalculationMode": "Interpretation", "Dictionary": {"DataSources": {"0": {"Ident": "StiDataTableSource", "Name": "srpmeta", "NameInSource": "srpmeta", "Alias": "srpmeta", "Columns": {"0": {"Name": "srp_id", "NameInSource": "srp_id", "Alias": "srp_id", "Type": "System.String"}, "1": {"Name": "srp_code", "NameInSource": "srp_code", "Alias": "srp_code", "Type": "System.String"}, "2": {"Name": "srp_name", "NameInSource": "srp_name", "Alias": "srp_name", "Type": "System.String"}, "3": {"Name": "srp_description", "NameInSource": "srp_description", "Alias": "srp_description", "Type": "System.String"}}}, "1": {"Ident": "StiDataTableSource", "Name": "root", "NameInSource": "root", "Alias": "root", "Columns": {"0": {"Name": "smt_date", "NameInSource": "smt_date", "Alias": "smt_date", "Type": "System.DateTime"}, "1": {"Name": "amount", "NameInSource": "amount", "Alias": "amount", "Type": "System.Decimal"}, "2": {"Name": "spr_cor_name", "NameInSource": "spr_cor_name", "Alias": "spr_cor_name", "Type": "System.String"}}}}}, "Pages": {"0": {"Ident": "StiPage", "Name": "Page1", "Guid": "cb8a7921488741878ce033b9112825bd", "Interaction": {"Ident": "StiInteraction"}, "Border": ";;;;;;;solid:Black", "Brush": "solid:", "Components": {"0": {"Ident": "StiReportTitleBand", "Name": "ppTitleBand1", "Guid