26	MG_DAILY_PO_RECV_01	進貨日報表	\N	SELECT M.RCV_TOTAL+M.RCV_TAX-M.RCV_NOT_CLEAN C_RECEVIED\r\n,P.PRD_UNIT,D.RCD_QTY*RCD_UNIT_PRICE C_SUB_TOTAL\r\n,M.RCV_TOTAL+M.RCV_TAX C_AMOUNT\r\n,COALESCE(D.RCD_PRD_NAME,P.PRD_NAME)C_PRD_NAME\r\n,M.* ,D.*,C.*,S.*\r\nFROM TBL_PO_RECV M INNER JOIN TBL_PO_RECV_DT D ON M.RCV_NO=D.RCV_NO\r\nINNER JOIN TBL_SUPPLIER C ON M.SUP_NO=C.SUP_NO\r\nINNER JOIN TBL_PRODUCT P ON D.PRD_NO=P.PRD_NO\r\n,TBL_SYS_PARAM S\r\n	WHERE M.RCV_STATUS>0	\N	ORDER BY M.RCV_DATE,M.RCV_NO,D.RCD_SEQNO	{"ReportVersion": "2026.3.3", "ReportGuid": "6bb205d3e23147e9bf3a2090dd2e9b18", "ReportName": "Report", "ReportAlias": "Report", "ReportCreated": "/Date(1789005813166+0800)/", "ReportChanged": "/Date(1789005813166+0800)/", "EngineVersion": "EngineV2", "ReportUnit": "Centimeters", "ScriptLanguage": "CSharp", "UsePlatformDependentScript": false, "CalculationMode": "Interpretation", "Dictionary": {"DataSources": {"0": {"Ident": "StiDataTableSource", "Name": "srpmeta", "NameInSource": "srpmeta", "Alias": "srpmeta", "Columns": {"0": {"Name": "srp_id", "NameInSource": "srp_id", "Alias": "srp_id", "Type": "System.String"}, "1": {"Name": "srp_code", "NameInSource": "srp_code", "Alias": "srp_code", "Type": "System.String"}, "2": {"Name": "srp_name", "NameInSource": "srp_name", "Alias": "srp_name", "Type": "System.String"}, "3": {"Name": "srp_description", "NameInSource": "srp_description", "Alias": "srp_description", "Type": "System.String"}}}, "1": {"Ident": "StiDataTableSource", "Name": "root", "NameInSource": "root", "Alias": "root", "Columns": {"0": {"Name": "c_recevied", "NameInSource": "c_recevied", "Alias": "c_recevied", "Type": "System.Decimal"}, "1": {"Name": "prd_unit", "NameInSource": "prd_unit", "Alias": "prd_unit", "Type": "System.String"}, "2": {"Name": "c_sub_total", "NameInSource": "c_sub_total", "Alias": "c_sub_total", "Type": "System.Decimal"}, "3": {"Name": "c_amount", "NameInSource": "c_amount", "Alias": "c_amount", "Type": "System.Decimal"}, "4": {"Name": "c_