27	MG_DAILY_SHIP_01	銷貨日報表	\N	SELECT M.SMT_TOTAL+M.SMT_TAX-M.SMT_NOT_CLEAN C_RECEVIED\r\n,P.PRD_UNIT,D.SMD_QTY*SMD_UNIT_PRICE C_SUB_TOTAL\r\n,M.SMT_TOTAL+M.SMT_TAX C_AMOUNT\r\n,COALESCE(D.SMD_PRD_NAME,P.PRD_NAME)C_PRD_NAME\r\n,M.* ,D.*,C.*,S.*\r\nFROM TBL_SHIP M INNER JOIN TBL_SHIP_DT D ON M.SMT_NO=D.SMT_NO\r\nINNER JOIN TBL_CUSTOMER C ON M.CUM_NO=C.CUM_NO\r\nINNER JOIN TBL_PRODUCT P ON D.PRD_NO=P.PRD_NO\r\n,TBL_SYS_PARAM S\r\n	WHERE M.SMT_STATUS>0   	\N	ORDER BY M.SMT_DATE,M.SMT_NO,D.SMD_SEQNO  	{"ReportVersion": "2026.3.3", "ReportGuid": "1e0d6285146c4229942f541f6c5d153d", "ReportName": "Report", "ReportAlias": "Report", "ReportCreated": "/Date(1789005813171+0800)/", "ReportChanged": "/Date(1789005813171+0800)/", "EngineVersion": "EngineV2", "ReportUnit": "Centimeters", "ScriptLanguage": "CSharp", "UsePlatformDependentScript": false, "CalculationMode": "Interpretation", "Dictionary": {"DataSources": {"0": {"Ident": "StiDataTableSource", "Name": "srpmeta", "NameInSource": "srpmeta", "Alias": "srpmeta", "Columns": {"0": {"Name": "srp_id", "NameInSource": "srp_id", "Alias": "srp_id", "Type": "System.String"}, "1": {"Name": "srp_code", "NameInSource": "srp_code", "Alias": "srp_code", "Type": "System.String"}, "2": {"Name": "srp_name", "NameInSource": "srp_name", "Alias": "srp_name", "Type": "System.String"}, "3": {"Name": "srp_description", "NameInSource": "srp_description", "Alias": "srp_description", "Type": "System.String"}}}, "1": {"Ident": "StiDataTableSource", "Name": "root", "NameInSource": "root", "Alias": "root", "Columns": {"0": {"Name": "c_recevied", "NameInSource": "c_recevied", "Alias": "c_recevied", "Type": "System.Decimal"}, "1": {"Name": "prd_unit", "NameInSource": "prd_unit", "Alias": "prd_unit", "Type": "System.String"}, "2": {"Name": "c_sub_total", "NameInSource": "c_sub_total", "Alias": "c_sub_total", "Type": "System.Decimal"}, "3": {"Name": "c_amount", "NameInSource": "c_amount", "Alias": "c_amount", "Type": "System.Decimal"}, "4": {"Name": "c_prd_