29	MG_DISCNT02	應付帳款折讓統計表	\N	SELECT A.SUP_NO\r\n  ,B.SUP_NAME\r\n  ,S.SPR_COR_NAME,SPR_TEL,SPR_FAX,SPR_ADDR\r\n  ,COALESCE(SUM(A.RCV_TOTAL),0) TOTAL_AP\r\n  ,COALESCE(SUM(C.PAD_AMOUNT),0) TOTAL_PAYED\r\n  ,COALESCE(SUM(A.RCV_NOT_CLEAN),0) TOTAL_NOT_CLEAN\r\n  ,COALESCE(SUM(C.PAD_DISCOUNT),0) TOTAL_DISCOUNT\r\n  ,CASE (COALESCE(SUM(C.PAD_AMOUNT),0)+COALESCE(SUM(C.PAD_DISCOUNT),0))\r\n    WHEN 0 THEN 0\r\n    ELSE\r\n      (COALESCE(SUM(C.PAD_DISCOUNT),0)/(COALESCE(SUM(C.PAD_AMOUNT),0)+COALESCE(SUM(C.PAD_DISCOUNT),0))) * 100\r\n    END Discount_Ratio\r\nFROM TBL_PO_RECV A\r\nINNER JOIN TBL_SUPPLIER B ON A.SUP_NO=B.SUP_NO\r\nLEFT JOIN (  SELECT C.RCV_NO\r\n                  ,COALESCE(SUM(C.PAD_AMOUNT),0) PAD_AMOUNT\r\n                  ,COALESCE(SUM(C.PAD_DISCOUNT),0) PAD_DISCOUNT\r\n            FROM TBL_AP_PAY_DT C\r\n            GROUP BY C.RCV_NO\r\n          )  C ON A.RCV_NO=C.RCV_NO\r\n,TBL_SYS_PARAM S	WHERE A.RCV_STATUS>0	GROUP BY A.SUP_NO ,B.SUP_NAME,S.SPR_COR_NAME,SPR_TEL,SPR_FAX,SPR_ADDR	ORDER BY SUM(C.PAD_DISCOUNT) DESC	{"ReportVersion": "2026.3.3", "ReportGuid": "8d687806390f4b239b6c4cda121e1093", "ReportName": "Report", "ReportAlias": "Report", "ReportCreated": "/Date(1789005813212+0800)/", "ReportChanged": "/Date(1789005813212+0800)/", "EngineVersion": "EngineV2", "ReportUnit": "Centimeters", "ScriptLanguage": "CSharp", "UsePlatformDependentScript": false, "CalculationMode": "Interpretation", "Dictionary": {"DataSources": {"0": {"Ident": "StiDataTableSource", "Name": "srpmeta", "NameInSource": "srpmeta", "Alias": "srpmeta", "Columns": {"0": {"Name": "srp_id", "NameInSource": "srp_id", "Alias": "srp_id", "Type": "System.String"}, "1": {"Name": "srp_code", "NameInSource": "srp_code", "Alias": "srp_code", "Type": "System.String"}, "2": {"Name": "srp_name", "NameInSource": "srp_name", "Alias": "srp_name", "Type": "System.String"}, "3": {"Name": "srp_description", "NameInSource": "srp_description", "Alias": "srp_description", "Type": "System.String"}}}, "1": {"Id