49	ZZ_FM_SHIP_RPT01	一般出貨單(含額)	一般出貨單(含額)	SELECT SYS.*,M.*,D.*,C.*,E.*\r\n       ,COALESCE(D.SMD_PRD_NAME,P.PRD_NAME) C_PROD_NAME\r\n       ,D.SMD_QTY*D.SMD_UNIT_PRICE AS C_SUB_TOTAL\r\n       ,M.SMT_TOTAL+M.SMT_TAX AS C_AMOUNT\r\nFROM TBL_SYS_PARAM SYS,TBL_SHIP M\r\nINNER JOIN TBL_SHIP_DT D ON M.SMT_NO=D.SMT_NO\r\nINNER JOIN TBL_CUSTOMER C ON M.CUM_NO=C.CUM_NO\r\nINNER JOIN TBL_PRODUCT P ON D.PRD_NO=P.PRD_NO\r\nINNER JOIN TBL_EMPLOYE E ON M.EPY_NO=E.EPY_NO	\N	\N	\N	{"ReportVersion": "2026.3.3", "ReportGuid": "4d742f8be0734d98947c026c712e3aa2", "ReportName": "Report", "ReportAlias": "Report", "ReportCreated": "/Date(1789006709929+0800)/", "ReportChanged": "/Date(1789006709929+0800)/", "EngineVersion": "EngineV2", "ReportUnit": "Centimeters", "ScriptLanguage": "CSharp", "UsePlatformDependentScript": false, "CalculationMode": "Interpretation", "Dictionary": {"DataSources": {"0": {"Ident": "StiDataTableSource", "Name": "srpmeta", "NameInSource": "srpmeta", "Alias": "srpmeta", "Columns": {"0": {"Name": "srp_id", "NameInSource": "srp_id", "Alias": "srp_id", "Type": "System.String"}, "1": {"Name": "srp_code", "NameInSource": "srp_code", "Alias": "srp_code", "Type": "System.String"}, "2": {"Name": "srp_name", "NameInSource": "srp_name", "Alias": "srp_name", "Type": "System.String"}, "3": {"Name": "srp_description", "NameInSource": "srp_description", "Alias": "srp_description", "Type": "System.String"}}}, "1": {"Ident": "StiDataTableSource", "Name": "root", "NameInSource": "root", "Alias": "root", "Columns": {"0": {"Name": "spr_period_start", "NameInSource": "spr_period_start", "Alias": "spr_period_start", "Type": "System.DateTime"}, "1": {"Name": "spr_cor_name", "NameInSource": "spr_cor_name", "Alias": "spr_cor_name", "Type": "System.String"}, "2": {"Name": "spr_tel", "NameInSource": "spr_tel", "Alias": "spr_tel", "Type": "System.String"}, "3": {"Name": "spr_fax", "NameInSource": "spr_fax", "Alias": "spr_fax", "Type": "System.String"}, "4": {"Name": "spr_addr", "NameInSource