28	MG_DISCNT01	應收帳款折讓統計表	\N	SELECT A.CUM_NO\r\n  ,B.CUM_NAME\r\n  ,S.SPR_COR_NAME,SPR_TEL,SPR_FAX,SPR_ADDR\r\n  ,COALESCE(SUM(A.SMT_TOTAL),0) TOTAL_AR\r\n  ,COALESCE(SUM(C.ARD_AMOUNT),0) TOTAL_RECEIVED\r\n  ,COALESCE(SUM(A.SMT_NOT_CLEAN),0) TOTAL_NOT_CLEAN\r\n  ,COALESCE(SUM(C.ARD_DISCOUNT),0) TOTAL_DISCOUNT\r\n  ,CASE (COALESCE(SUM(C.ARD_AMOUNT),0)+COALESCE(SUM(C.ARD_DISCOUNT),0))\r\n    WHEN 0 THEN 0\r\n    ELSE\r\n      (COALESCE(SUM(C.ARD_DISCOUNT),0)/(COALESCE(SUM(C.ARD_AMOUNT),0)+COALESCE(SUM(C.ARD_DISCOUNT),0))) * 100\r\n    END Discount_Ratio\r\nFROM TBL_SHIP A\r\nINNER JOIN TBL_CUSTOMER B ON A.CUM_NO=B.CUM_NO\r\nLEFT JOIN (  SELECT C.SMT_NO\r\n                  ,COALESCE(SUM(C.ARD_AMOUNT),0) ARD_AMOUNT\r\n                  ,COALESCE(SUM(C.ARD_DISCOUNT),0) ARD_DISCOUNT\r\n            FROM TBL_AR_RECV_DT C\r\n            GROUP BY C.SMT_NO\r\n          )  C ON A.SMT_NO=C.SMT_NO\r\n,TBL_SYS_PARAM S	WHERE A.SMT_STATUS>0\r\n	GROUP BY A.CUM_NO ,B.CUM_NAME,S.SPR_COR_NAME,SPR_TEL,SPR_FAX,SPR_ADDR\r\n	ORDER BY SUM(C.ARD_DISCOUNT) DESC	{"ReportVersion": "2026.3.3", "ReportGuid": "a53646a11a7b4e3aaadf010c9bf5323e", "ReportName": "Report", "ReportAlias": "Report", "ReportCreated": "/Date(1789005813192+0800)/", "ReportChanged": "/Date(1789005813192+0800)/", "EngineVersion": "EngineV2", "ReportUnit": "Centimeters", "ScriptLanguage": "CSharp", "UsePlatformDependentScript": false, "CalculationMode": "Interpretation", "Dictionary": {"DataSources": {"0": {"Ident": "StiDataTableSource", "Name": "srpmeta", "NameInSource": "srpmeta", "Alias": "srpmeta", "Columns": {"0": {"Name": "srp_id", "NameInSource": "srp_id", "Alias": "srp_id", "Type": "System.String"}, "1": {"Name": "srp_code", "NameInSource": "srp_code", "Alias": "srp_code", "Type": "System.String"}, "2": {"Name": "srp_name", "NameInSource": "srp_name", "Alias": "srp_name", "Type": "System.String"}, "3": {"Name": "srp_description", "NameInSource": "srp_description", "Alias": "srp_description", "Type": "System.String"}}}, "1": {"Ident": "StiDataTableSource", "Name": "root", "NameInSource": "root", "Alias": "root", "Columns": {"0": {"Name": "cum_no", "NameInSource": "cum_no", "Alias": "cum_no", "Type": "System.String"}, "1": {"Name": "cum_name", "NameInSource": "cum_name", "Alias": "cum_name", "Type": "System.String"}, "2": {"Name": "spr_cor_name", "NameInSource": "spr_cor_name", "Alias": "spr_cor_name", "Type": "System.String"}, "3": {"Name": "spr_tel", "NameInSource": "spr_tel", "Alias": "spr_tel", "Type": "System.String"}, "4": {"Name": "spr_fax", "NameInSource": "spr_fax", "Alias": "spr_fax", "Type": "System.String"}, "5": {"Name": "spr_addr", "NameInSource": "spr_addr", "Alias": "spr_addr", "Type": "System.String"}, "6": {"Name": "total_ar", "NameInSource": "total_ar", "Alias": "total_ar", "Type": "System.Decimal"}, "7": {"Name": "total_received", "NameInSource": "total_received", "Alias": "total_received", "Type": "System.Decimal"}, "8": {"Name": "total_not_clean", "NameInSource": "total_not_clean", "Alias": "total_not_clean", "Type": "System.Decimal"}, "9": {"Name": "total_discount", "NameInSource": "total_discount", "Alias": "total_discount", "Type": "System.Decimal"}, "10": {"Name": "discount_ratio", "NameInSource": "discount_ratio", "Alias": "discount_ratio", "Type": "System.Decimal"}}}}}, "Pages": {"0": {"Ident": "StiPage", "Name": "Page1", "Guid": "7262ae3e8bd94319818d581364505cb9", "Interaction": {"Ident": "StiInteraction"}, "Border": ";;;;;;;solid:Black", "Brush": "solid:", "Components": {"0": {"Ident": "StiPageHeaderBand", "Name": "ppHeaderBand1", "Guid": "3dd12d9c9779448bbe9ed5475213ac89", "CanGrow": true, "ClientRectangle": "0,0.0,19.7379,3.3338", "Interaction": {"Ident": "StiInteraction"}, "Border": ";;;;;;;solid:Black", "Brush": "solid:", "Components": {"0": {"Ident": "StiText", "Name": "ppLabel2", "Guid": "3d40fb950c6345f7827d3b9e58937297", "ClientRectangle": "0.635,0.4498,1.7727,0.4233", "Interaction": {"Ident": "StiInteraction"}, "Text": {"Value": "製表日期："}, "Font