55	AA-MG_AR_002_COPY	應收帳款明細表(已) 複製	\N	SELECT M.SMT_TOTAL+M.SMT_TAX-M.SMT_NOT_CLEAN C_RECEVIED\n      , P.PRD_UNIT,\n      D.SMD_QTY * SMD_UNIT_PRICE C_SUB_TOTAL,\n      M.SMT_TOTAL + M.SMT_TAX C_AMOUNT,\n      COALESCE (D.SMD_PRD_NAME, P.PRD_NAME) C_PRD_NAME,\n      M.SMT_TAX / T1.CNT C_AVG_TAX,\n      (M.SMT_TOTAL + M.SMT_TAX - M.SMT_NOT_CLEAN) / T1.CNT C_AVG_RECEIVED,\n      M.SMT_NOT_CLEAN / T1.CNT C_AVG_NOT_CLEAN,\n      (M.SMT_TOTAL + M.SMT_TAX) / T1.CNT C_AVG_AMOUNT,\n      T1.CNT,\n      M.*,\n      D.*,\n      C.cum_name,\n      S.spr_cor_name\nFROM TBL_SHIP M \nINNER JOIN TBL_SHIP_DT D ON M.SMT_NO=D.SMT_NO\nINNER JOIN TBL_CUSTOMER C ON M.CUM_NO=C.CUM_NO\nINNER JOIN TBL_PRODUCT P ON D.PRD_NO=P.PRD_NO\nINNER JOIN \n( SELECT M.SMT_NO,COUNT(*) CNT\n  FROM TBL_SHIP M \n  INNER JOIN TBL_SHIP_DT D ON M.SMT_NO=D.SMT_NO\n  GROUP BY M.SMT_NO \n) T1 ON M.SMT_NO=T1.SMT_NO  \nINNER JOIN TBL_SYS_PARAM S ON 1=1	WHERE M.SMT_STATUS>0	\N	ORDER BY M.CUM_NO,M.SMT_DATE,M.SMT_NO,D.SMD_SEQNO	{\n  "ReportVersion": "2026.3.3",\n  "ReportGuid": "326ebc8a9ed39aaba9e939157a8b3f79",\n  "ReportName": "Report",\n  "ReportAlias": "Report",\n  "ReportFile": "Report.mrt",\n  "ReportCreated": "/Date(1788939784000+0800)/",\n  "ReportChanged": "/Date(1789005272000+0800)/",\n  "EngineVersion": "EngineV2",\n  "ReportUnit": "Centimeters",\n  "ScriptLanguage": "CSharp",\n  "UsePlatformDependentScript": false,\n  "CalculationMode": "Interpretation",\n  "Dictionary": {\n    "DataSources": {\n      "0": {\n        "Ident": "StiDataTableSource",\n        "Name": "srpmeta",\n        "Alias": "srpmeta",\n        "Columns": {\n          "0": {\n            "Name": "srp_id",\n            "NameInSource": "srp_id",\n            "Alias": "srp_id",\n            "Type": "System.Decimal"\n          },\n          "1": {\n            "Name": "srp_code",\n            "NameInSource": "srp_code",\n            "Alias": "srp_code",\n            "Type": "System.String"\n          },\n          "2": {\n            "Name": "srp_name",\n            "NameInSource": "srp_name",\n            "Alias": "srp_name",\n            "Type": "System.String"\n          },\n          "3": {\n            "Name": "srp_description",\n            "NameInSource": "srp_description",\n            "Alias": "srp_description",\n            "Type": "System.String"\n          }\n        },\n        "NameInSource": "srpmeta.srpmeta"\n      },\n      "1": {\n        "Ident": "StiDataTableSource",\n        "Name": "root",\n        "Alias": "root",\n        "Columns": {\n          "0": {\n            "Name": "c_recevied",\n            "NameInSource": "c_recevied",\n            "Alias": "c_recevied",\n            "Type": "System.Decimal"\n          },\n          "1": {\n            "Name": "prd_unit",\n            "NameInSource": "prd_unit",\n            "Alias": "prd_unit",\n            "Type": "System.String"\n          },\n          "2": {\n            "Name": "c_sub_total",\n            "NameInSource": "c_sub_total",\n            "Alias": "c_sub_total",\n            "Type": "System.Decimal"\n          },\n          "3": {\n            "Name": "c_amount",\n            "NameInSource": "c_amount",\n            "Alias": "c_amount",\n            "Type": "System.Decimal"\n          },\n          "4": {\n            "Name": "c_prd_name",\n            "NameInSource": "c_prd_name",\n            "Alias": "c_prd_name",\n            "Type": "System.String"\n          },\n          "5": {\n            "Name": "c_avg_tax",\n            "NameInSource": "c_avg_tax",\n            "Alias": "c_avg_tax",\n            "Type": "System.Decimal"\n          },\n          "6": {\n            "Name": "c_avg_received",\n            "NameInSource": "c_avg_received",\n            "Alias": "c_avg_received",\n            "Type": "System.Decimal"\n          },\n          "7": {\n            "Name": "c_avg_not_clean",\n            "NameInSource": "c_avg_not_clean",\n            "Alias": "c_avg_not_clean",\n            "Type": "System.Decimal"